using Azure.Storage.Files.Shares;
using Azure.Storage.Files.Shares.Models;

class DEVDocuExpImpJournalAzureConnector
{
    DEVDocuExpImpJournalTable  journalTable;
    ShareClient                share;
    ShareDirectoryClient       rootDir;
    ShareDirectoryClient       currentDir;

    System.Threading.CancellationToken  tokenNull;
    System.Object                       objNull;
}

Method.Source:
public void connect()
{
    DEVDocuExpImpJournalName   journalName = DEV::checkRecordExist(journalTable.journalName());

    try
    {
        share = new ShareClient(journalName.AzureConnectionString, journalName.AzureShareReference);
        boolean isExists;
        isExists = share.Exists(tokenNull);
        if (! isExists)
        {
            throw error(strFmt("Share '%1' doesn't exists", journalName.AzureShareReference));
        }
        rootDir = share.GetRootDirectoryClient();
        isExists = rootDir.Exists(tokenNull);
        if (! isExists)
        {
            throw error(strFmt("Root directory '%1' doesn't exists", journalName.AzureShareReference));
        }
    }
    catch( Exception::CLRError )
    {
        throw error(AifUtil::getClrErrorMessage());
    }

}

public void testConnection()
{
    boolean testIsOK;
    try
    {
        this.connect();
        this.getDirectory(journalTable.AzureLocation);
        testIsOK = true;
    }
    catch( Exception::CLRError )
    {
        throw error(AifUtil::getClrErrorMessage());
    }
    catch
    {
    }
    if (testisOK)
    {
        info("Test is OK");
    }
    else
    {
        throw error("Test Failed");
    }
}

public ShareDirectoryClient  getDirectory(FolderName  _folderName)
{
    ShareDirectoryClient fileDir = rootDir.GetSubdirectoryClient(_folderName);

    boolean isExists = fileDir.Exists(tokenNull);
    if (! isExists)
    {
        throw error(strFmt("Directory '%1' doesn't exists", _folderName));
    }
    return fileDir;
}

public System.IO.MemoryStream  readFile(str _fileName,  ShareDirectoryClient _fileDir = currentDir)
{
    System.IO.MemoryStream memoryStream;

    ShareFileClient file = _fileDir.GetFileClient(_fileName);

    // Ensure that the file exists.
    boolean isExists = file.Exists(tokenNull);
    if (isExists)
    {
        memoryStream = new System.IO.MemoryStream();
        ShareFileDownloadInfo download = file.Download(objNull, tokenNull);
        System.IO.Stream  downloadContent = download.Content;

        downloadContent.CopyTo(memoryStream);
        memoryStream.Position = 0;
    }

    return memoryStream;
}

public static DEVDocuExpImpJournalAzureConnector construct(DEVDocuExpImpJournalTable  _journalTable)
{
    return new DEVDocuExpImpJournalAzureConnector(_journalTable);
}
